  "interpretation": "主应许：信我的人也要做我所做的事，并且要做比这更大的事，因为我往父那里去。这更大的事，不是说门徒比主更伟大，而是复活升天的基督要赐下圣灵，福音借着教会传到地极，使万民得救。主又应许，奉祂的名无论求什么，祂必成就，为要叫父因儿子得荣耀。奉主的名祈求，是照着祂的心意、为祂的荣耀而求。接着主说：你们若爱我，就必遵守我的命令。顺服是爱的果子，不是换取恩典的条件。",
