   "title": "Hated Without Reason",
   "interpretation": "Jesus explains why the world will hate His disciples: “they do not know the One who sent Me.” He came, spoke, and did works no one else had done, so those who rejected Him have no excuse. “Whoever hates Me hates My Father as well.” To reject Christ is finally to reject God Himself. All this fulfilled the Scripture: “They hated Me without reason.” Christ was hated for no reason, yet He willingly died for those who hated Him. That is the wonder of the gospel. We too were sinners without excuse until His grace opened our eyes. May we meet those who reject the gospel with compassion, not resentment.",
