   "confession": "主啊，我承认我常因胆怯而闭口，怕被拒绝、怕说不好，就不为主作见证。我也常靠自己的口才，而不倚靠圣灵的能力。",
   "thanksgiving": "感谢祢差圣灵来到我心里，使我认识基督，又不撇下我独自作见证。感谢祢使用软弱的人来传扬祢的福音。",
   "supplication": "求圣灵今天给我一个机会，向一位还不认识主的朋友诚实地讲述祢的恩典。求祢也使我们的教会在这个城市中，为基督作美好的见证。"
