   "interpretation": "Amid the world's hostility, Jesus gives His disciples a promise: the Advocate, “the Spirit of truth who proceeds from the Father,” will come, and “He will testify about Me.” The Spirit's work always points to Christ. Then Jesus adds, “And you also must testify, because you have been with Me from the beginning.” Our witness does not rest on our eloquence or courage. The Spirit first testifies to Christ in people's hearts, and we follow by telling what we have seen and known of Him. Today we need not be anxious about what to say. We can rely on the Spirit and simply tell what Christ has done for us.",
