    "adoration": "Lord Jesus, I praise You for Your wise plan! You went to the Father not to abandon us but to accomplish our salvation, and You sent the Advocate to be with us forever. We are never left as orphans.",
    "confession": "Lord, I confess that, like the disciples, I fix my eyes on what I am losing and am filled with sorrow, never asking where You are going or what You are doing. I often think my plans are better than Yours. Forgive my shortsightedness.",
    "thanksgiving": "Thank You for going to the cross, rising, and ascending to accomplish salvation for me. Thank You for sending the Spirit to live in me, so that I can know Your presence anywhere.",
    "supplication": "When I face loss and change, give me faith to see Your good purpose. Comfort brothers and sisters going through goodbyes and grief, and let them know the Advocate is near."
