   "thanksgiving": "感谢祢借着圣灵的责备领我归向基督，使我不是靠自己的义，而是披上基督的义。感谢祢在十字架上胜过了撒但，使我不再受它辖制。",
   "supplication": "求圣灵在我还没信主的亲友心中动工，使他们知罪悔改，信靠耶稣。求祢也使我对罪保持敏感，一被责备就回到祢面前。"
