   "thanksgiving": "感谢祢看出我心里的疑问和眼泪，没有轻看我的忧愁。感谢祢借着十字架和复活，使我的忧愁有一天要变为永远的喜乐。",
   "supplication": "求祢安慰那些正在痛哭的家庭，在病痛、失落和破碎中让他们看见复活的盼望。求祢使我在忧愁时仍然信靠祢，等候祢再见我们的那一天。"
