   "confession": "主啊，我承认我常常不祷告，宁可自己想办法；就算祷告，也常把奉主的名当作一句套话，心里并不倚靠基督。",
   "thanksgiving": "感谢祢因着基督的名接纳我这个罪人，使我可以坦然无惧地来到施恩的宝座前。感谢祢应许叫我的喜乐满足。",
