   "confession": "主啊，我承认我常想靠自己的意志改变自己，却很少让祢的话语真正进入我的心。我也常把信仰只留在教会里，忘了自己是被差遣的人。求祢赦免我分裂的生活。",
   "thanksgiving": "感谢主耶稣为我的缘故将自己分别为圣，献上了自己。感谢祢不是让我独自挣扎成圣，而是亲自在我里面动工。祢的道不是重担，而是恩赐。",
   "supplication": "求祢用祢的道每天洁净我的思想、言语和行为。求祢差遣我在今天所遇见的人当中作基督的见证，也赐给我们教会宣教的心志。使我一天比一天更爱祢的话语。"
