   "confession": "主啊，我承认我常以为自己没有杀人就是好人，却任由怒气在心里滋长。我曾用刻薄的话贬低家人和弟兄姊妹，也在心里轻看他们。",
   "thanksgiving": "感谢主耶稣为我心中的怒气和口中的恶言受了审判。祢没有向我发烈怒，反而在十字架上向我显明怜悯。",
   "supplication": "求圣灵在我发怒时提醒我，叫我快快地听，慢慢地说，慢慢地动怒；在开口之前，让我想起祢向我所施的怜悯。求祢医治我们家中和教会里因怒气而受伤的关系，使我们彼此饶恕。"
