   "confession": "主啊，我承认我的爱常是有条件的：对我有好处的，我才热情；不熟悉、不喜欢的人，我就冷淡。我的爱和世人的爱常常没有两样。",
   "thanksgiving": "感谢主耶稣替我活出了完全的爱，又把祢完全的义归给我。感谢祢不因我的不完全就丢弃我，仍天天借着圣灵在我身上作工。",
