   "interpretation": "If we love only those who love us, even tax collectors do the same. A disciple's love must go beyond trading favors. So Jesus sums up the section: “Be perfect, therefore, as your heavenly Father is perfect.” This perfection is the complete, impartial love of the Father. The standard is far beyond our own strength, and that is exactly what drives us to Christ, the only one who is perfect, whose righteousness is counted as ours. In Him, the Spirit is shaping us day by day into the likeness of our Father. Today, go out of your way to greet someone you would normally overlook.",
