   "thanksgiving": "感谢祢藉着主耶稣收纳我作祢的儿女，使我可以坦然来到祢面前。感谢祢的国已经在基督里临到，将来也必完全显明。",
   "supplication": "求祢使我今天的言语和工作都叫人尊祢的名为圣。求祢的国降临在我的家庭和教会中，也求祢使福音传到还不认识祢的人那里。帮助我今天以先求祢荣耀的心来祷告。"
