   "title": "Forgiven People Forgive",
   "interpretation": "Right after the Lord's Prayer, Jesus returns to one line: “if you forgive men their trespasses, your heavenly Father will also forgive you.” And if we refuse to forgive, neither will the Father forgive us. This does not mean we earn salvation by forgiving others. It means that those who have truly tasted God's forgiveness will learn to forgive. Someone who clings to resentment shows that he has not grasped how much he has been forgiven. On the cross Christ prayed for those who crucified Him, and His grace can soften our hearts too. Today, consider who needs your forgiveness.",
