   "confession": "主啊，我承认我常想两边都要：主日敬拜祢，平日却被钱财牵着走。我嘴上说祢是我的主，花钱和做决定时却常常听玛门的声音。",
   "thanksgiving": "感谢主耶稣用祂自己的宝血把我买赎回来，使我不再作罪和钱财的奴仆。感谢祢是我永远可以信靠的主。",
   "supplication": "求祢使我的心专一，单单事奉祢。求祢帮助我们的家庭在金钱上忠心、知足，也求祢保守那些正被债务和贪心捆绑的人，使他们在基督里得自由。"
