  "title": "先求祂的国和祂的义",
  "interpretation": "这段是主耶稣论忧虑的总结：不要忧虑说，吃什么？喝什么？穿什么？这都是外邦人所求的，你们需用的这一切东西，你们的天父是知道的。门徒的人生目标不同：要先求祂的国和祂的义，这些东西都要加给你们了。祂的义首先是在基督里白白赐给我们的，然后在我们生命中结出果子。所以不要为明天忧虑，一天的难处一天当就够了。今天，把最好的时间和心力先交给神。",
