   "adoration": "天父，我赞美祢是无所不知的父，我还没有开口，祢早已知道我需用的一切。祢的国是永远的国，祢的义是完全的义，每一个明天都在祢手中。",
   "confession": "主啊，我承认我常把祢的国放在最后，先求自己的安稳和成就，再把剩下的一点给祢。我也常为明天的事提前担忧。",
   "thanksgiving": "感谢祢在基督里把祢的义白白赐给我，使我这不义的人被称为义。感谢祢一天一天地供应我，从未误事。",
   "supplication": "求祢帮助我今天先寻求祢的国，在工作、家庭和时间安排上把祢摆在首位。求祢赐给我们的教会合一的心，一同为福音广传摆上。当我为明天焦虑时，帮助我交托给祢，忠心做好今天的事。"
