    "confession": "Lord, I confess that I hold grudges against some brothers and sisters. I am polite on the outside but distant on the inside. I thought it was a small thing, not realizing it has already dimmed my eyes. Forgive me.",
    "thanksgiving": "Thank You for placing me in the family of the church and giving me brothers and sisters to love. Thank You for forgiving me first, so that I too have strength to forgive others.",
