   "thanksgiving": "感谢祢把我从这个世界中拣选出来，使我不再属世界。感谢祢让我看见世上的荣华都要过去，而遵行祢旨意的人永远常存。",
   "supplication": "求祢帮助我分辨生活中哪些是肉体的情欲、眼目的情欲和今生的骄傲，并且勇敢地放下。求祢使我和我的家把心思放在永远的事上。"
