  "prayer": {
   "adoration": "天父，我赞美祢！主耶稣为我们舍命，让我们看见了真正的爱。祢比我们的心大，一切事没有不知道的，祢的怜悯比我的自责更深。",
   "confession": "主啊，我承认我的爱常常停在言语和舌头上，说得多，做得少。看见别人有需要，我常找理由塞住怜恤的心。求祢赦免我的自私。",
   "thanksgiving": "感谢主耶稣为我舍命，使我知道何为爱。感谢祢在我的心责备我时，仍然用祢的怜悯和赦免安慰我，使我的心在祢面前可以安稳。",
   "supplication": "求祢开我的眼睛，看见身边真正有需要的人，并给我舍己的心，用时间、金钱和陪伴去帮助他们。愿我的爱在行为和诚实上显明出来。"
  },
  "closing": "奉主耶稣基督的名祷告，阿们！",
