  "interpretation": "约翰看见这教会的儿女有遵行真理的，就甚欢喜；同时他也劝勉：「我们大家要彼此相爱。」这不是一条新命令，而是从起初就从主耶稣领受的。约翰把爱和命令连在一起：「我们若照祂的命令行，这就是爱。」爱不是一种模糊的感觉，而是顺服神的具体行动。真理需要爱心来活出，爱心也需要真理来引导。这个主日，愿我们在教会中把这命令活出来。",
